function validateBook(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, reason: "record must be an object" };
  }
  if (typeof value.title !== "string" || !value.title.trim()) {
    return { ok: false, reason: "title is required" };
  }
  if (!Number.isInteger(value.id) || value.id <= 0) {
    return { ok: false, reason: "id must be a positive integer" };
  }
  return { ok: true, value: { id: value.id, title: value.title.trim() } };
}
console.log(validateBook({ id: 2, title: " Mti " }).value.title);
console.log(validateBook({ id: 0, title: "Mti" }).reason);

