import { setTimeout as delay } from "node:timers/promises";
async function readSection(name, ms) {
  await delay(ms);
  return name;
}
const [catalog, notes] = await Promise.all([
  readSection("catalog", 10),
  readSection("notes", 5),
]);
console.log(catalog, notes);

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
const dir = await mkdtemp(join(tmpdir(), "marian-shelf-practice-"));
try {
  const file = join(dir, "records.json");
  const records = [{ id: 1, title: "Mti wa Hadithi" }];
  await writeFile(file, JSON.stringify(records, null, 2), "utf8");
  const text = await readFile(file, "utf8");
  const parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new TypeError("Expected a list");
  console.log(parsed[0].title);
} finally { await rm(dir, { recursive: true, force: true }); }
